const PriceTrialUnitPriceOverrideSchema = z
  .strictObject({
    country_codes: z
      .array(CountryCodeSchema)
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description:
          'Supported two-letter ISO 3166-1 alpha-2 country code. Customers located in the listed countries are charged the override price.',
      }),
    unit_price: MoneyOptionalCurrencySchema.openapi({
      description:
        'Override price. This price applies to customers located in the countries for this unit price override.',
    }),
  })
  .openapi({
    required: ['country_codes', 'unit_price'],
    description:
      'Override price for the trial period. Customers located in the listed countries are charged the override price during the trial.',
    title: 'Unit price trial override',
  })
  .openapi('PriceTrialUnitPriceOverride')

