const BusinessSchema = z
  .object({
    id: BusinessIdSchema.openapi({ readOnly: true }),
    customer_id: CustomerIdSchema.openapi({
      description: 'Paddle ID for the customer related to this business, prefixed with `ctm_`.',
      readOnly: true,
    }),
    name: NameSchema.openapi({ description: 'Name of this business.' }),
    company_number: z
      .union([z.string(), z.null().nullable()])
      .openapi({ description: 'Company number for this business.', examples: ['123456789'] }),
    tax_identifier: z
      .union([z.string(), z.null().nullable()])
      .openapi({ description: 'Tax or VAT Number for this business.', examples: ['AB0123456789'] }),
    status: StatusSchema.default('active'),
    contacts: z
      .array(BusinessContactsItemSchema)
      .max(100)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({
        description:
          'List of contacts related to this business, typically used for sending invoices.',
      }),
    created_at: CreatedAtSchema.openapi({ readOnly: true }),
    updated_at: UpdatedAtSchema.openapi({ readOnly: true }),
    custom_data: z
      .union([CustomDataSchema, z.null().nullable()])
      .openapi({ description: 'Your own structured key-value data.' }),
    import_meta: z
      .union([ImportMetaSchema, z.null().nullable()])
      .openapi({
        description: 'Import information for this entity. `null` if this entity is not imported.',
        'x-external-readOnly': true,
      }),
  })
  .openapi({
    required: [
      'id',
      'customer_id',
      'name',
      'company_number',
      'tax_identifier',
      'status',
      'contacts',
      'created_at',
      'updated_at',
      'custom_data',
      'import_meta',
    ],
    description: 'Represents a business entity.',
    title: 'Business',
  })
  .openapi('Business')

