const AdjustmentSchema = z
  .object({
    id: AdjustmentIdSchema.openapi({ readOnly: true }),
    action: AdjustmentActionSchema,
    type: AdjustmentTypeSchema.default('partial'),
    transaction_id: TransactionIdSchema.openapi({
      description:
        'Paddle ID of the transaction that this adjustment is for, prefixed with `txn_`.',
    }),
    subscription_id: z
      .union([SubscriptionIdSchema, z.null().nullable()])
      .openapi({
        description:
          'Paddle ID for the subscription related to this adjustment, prefixed with `sub_`.\nSet automatically by Paddle based on the `subscription_id` of the related transaction.',
        readOnly: true,
      }),
    customer_id: CustomerIdSchema.openapi({
      description:
        'Paddle ID for the customer related to this adjustment, prefixed with `ctm_`.\nSet automatically by Paddle based on the `customer_id` of the related transaction.',
      readOnly: true,
    }),
    reason: z
      .string()
      .openapi({
        description:
          'Why this adjustment was created. Appears in the Paddle dashboard. Retained for record-keeping purposes.',
      }),
    credit_applied_to_balance: z
      .union([z.boolean(), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "Whether this adjustment was applied to the related customer's credit balance. Only returned for `credit` adjustments.",
        readOnly: true,
      }),
    currency_code: CurrencyCodeSchema.openapi({
      description:
        'Three-letter ISO 4217 currency code for this adjustment. Set automatically by Paddle based on the `currency_code` of the related transaction.',
      readOnly: true,
    }),
    status: AdjustmentStatusSchema.openapi({ readOnly: true }),
    items: z
      .array(
        z
          .object({
            id: AdjustmentItemIdSchema.openapi({
              description: 'Unique Paddle ID for this adjustment item, prefixed with `adjitm_`.',
              readOnly: true,
            }),
            item_id: TransactionItemIdSchema.openapi({
              description:
                'Paddle ID for the transaction item that this adjustment item relates to, prefixed with `txnitm_`.',
            }),
            type: AdjustmentItemTypeSchema.openapi({
              description:
                'Type of adjustment for this transaction item. `tax` adjustments are automatically created by Paddle.\nInclude `amount` when creating a `partial` adjustment.',
            }),
            amount: z
              .union([z.string(), z.null().nullable()])
              .openapi({
                description:
                  'Amount adjusted for this transaction item. Required when item `type` is `partial`.',
              }),
            proration: z
              .union([TransactionItemProrationSchema, z.null().nullable()])
              .openapi({
                description: 'How proration was calculated for this adjustment item.',
                readOnly: true,
              }),
            totals: AdjustmentItemTotalsSchema.openapi({ readOnly: true }),
          })
          .openapi({ required: ['id', 'item_id', 'type', 'amount', 'proration', 'totals'] }),
      )
      .min(1)
      .max(100)
      .openapi({
        description:
          'List of items on this adjustment. Required if `type` is not populated or set to `partial`.',
      }),
    totals: AdjustmentTotalsSchema.openapi({ readOnly: true }),
    payout_totals: z
      .union([AdjustmentPayoutTotalsSchema, z.null().nullable()])
      .openapi({
        description: 'Breakdown of how this adjustment affects your payout balance.',
        readOnly: true,
      }),
    tax_rates_used: z.array(AdjustmentTaxRatesUsedSchema).openapi({ readOnly: true }),
    created_at: CreatedAtSchema.openapi({ readOnly: true }),
    updated_at: UpdatedAtSchema.openapi({ readOnly: true }),
  })
  .openapi({
    required: [
      'id',
      'action',
      'type',
      'transaction_id',
      'subscription_id',
      'customer_id',
      'reason',
      'currency_code',
      'status',
      'items',
      'totals',
      'payout_totals',
      'tax_rates_used',
      'created_at',
      'updated_at',
    ],
    description: 'Represents an adjustment entity.',
    title: 'Adjustment',
  })
  .openapi('Adjustment')

