const TransactionStatusCreateSchema = z
  .enum(['draft', 'ready', 'billed', 'paid', 'completed', 'canceled', 'past_due'])
  .openapi({
    description:
      'Status of this transaction. You may set a transaction to `billed` or `canceled`, other statuses are set automatically by Paddle. Automatically-collected transactions may return `completed` if payment is captured successfully, or `past_due` if payment failed.',
    title: 'TransactionStatusCreate',
    'x-enum-descriptions': {
      draft: {
        description:
          'Transaction is missing required fields. Typically the first stage of a checkout before customer details are captured.',
        readOnly: true,
      },
      ready: {
        description:
          'Transaction has all of the required fields to be marked as `billed` or `completed`.',
        readOnly: true,
      },
      billed: {
        description:
          'Transaction has been updated to `billed`. Billed transactions get an invoice number and are considered a legal record. They cannot be updated, only canceled. Typically used as part of an invoice workflow.',
      },
      paid: {
        description: 'Transaction is fully paid, but has not yet been processed internally.',
        readOnly: true,
      },
      completed: { description: 'Transaction is fully paid and processed.', readOnly: true },
      canceled: {
        description:
          "Transaction has been updated to `canceled`. If an invoice, it's no longer due.",
      },
      past_due: {
        description:
          'Transaction is past due. Occurs for automatically-collected transactions when the related subscription is in dunning, and for manually-collected transactions when no payment has been received 24 hours after the due date.',
        readOnly: true,
      },
    },
  })
  .openapi('TransactionStatusCreate')

const DiscountCustomSchema = z
  .strictObject({
    description: z
      .string()
      .min(1)
      .max(500)
      .openapi({
        description:
          'Short description for this discount for your reference. Not shown to customers.',
      }),
    type: DiscountTypeSchema.openapi({
      description:
        'Type of discount. Determines how this discount impacts the checkout or transaction total.',
      title: 'DiscountType',
      'x-enum-descriptions': {
        flat: {
          description:
            'Discounts a checkout or transaction by a flat amount, for example -$100. Requires `currency_code`.',
        },
        flat_per_seat: {
          description:
            'Discounts a checkout or transaction by a flat amount per unit, for example -$100 per user. Requires `currency_code`.',
        },
        percentage: {
          description:
            'Discounts a checkout or transaction by a percentage of the total, for example -10%. Maximum 100%.',
        },
      },
    }),
    amount: z
      .string()
      .openapi({
        description:
          'Amount to discount by. For `percentage` discounts, must be an amount between `0.01` and `100`. For `flat` and `flat_per_seat` discounts, amount in the lowest denomination for a currency.',
      }),
    recur: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Whether this discount applies for multiple subscription billing periods (`true`) or not (`false`). If omitted, defaults to `false`.',
      }),
    maximum_recurring_intervals: z
      .union([z.int(), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "Number of subscription billing periods that this discount recurs for. Requires `recur`. `null` if this discount recurs forever.\n\nSubscription renewals, midcycle changes, and one-time charges billed to a subscription aren't considered a redemption. `times_used` is not incremented in these cases.",
      }),
    custom_data: z
      .union([CustomDataSchema, z.null().nullable()])
      .exactOptional()
      .openapi({ description: 'Your own structured key-value data.' }),
    restrict_to: z
      .union([z.array(z.string()), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Product or price IDs that this discount is for. When including a product ID, all prices for that product can be discounted. `null` if this discount applies to all products and prices.',
      }),
  })
  .openapi({
    required: ['description', 'type', 'amount'],
    description: 'Represents a discount entity for a custom, non-catalog discount.',
    title: 'DiscountCustom',
  })
  .openapi('DiscountCustom')

