const CustomerPortalSessionCreateSchema = z
  .strictObject({
    subscription_ids: z
      .array(SubscriptionIdSchema)
      .max(25)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({
        description:
          'List of subscriptions to create authenticated customer portal deep links for.',
      }),
  })
  .openapi({
    description: 'Represents a customer portal session creation request.',
    title: 'CustomerPortalSessionCreate',
    required: [],
  })
  .openapi('CustomerPortalSessionCreate')

