const DiscountCreateSchema = z
  .strictObject({
    id: DiscountIdSchema.exactOptional().openapi({ readOnly: true }),
    status: DiscountStatusSchema.default('active').exactOptional().openapi({ readOnly: true }),
    description: z
      .string()
      .min(1)
      .max(500)
      .openapi({
        description:
          'Short description for this discount for your reference. Not shown to customers.',
      }),
    enabled_for_checkout: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Whether this discount can be redeemed by customers at checkout (`true`) or not (`false`).',
      }),
    code: z
      .union([DiscountCodeSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Unique code that customers can use to redeem this discount at checkout. Use letters and numbers only, up to 32 characters. Not case-sensitive.\n\nIf omitted and `enabled_for_checkout` is `true`, Paddle generates a random 10-character code.',
      }),
    type: DiscountTypeSchema.openapi({
      description:
        'Type of discount. Determines how this discount impacts the checkout or transaction total.',
      title: 'DiscountType',
    }),
    mode: DiscountModeSchema.default('standard')
      .exactOptional()
      .openapi({
        description:
          'Discount mode. Standard discounts are considered part of your catalog and are shown in the Paddle dashboard. If omitted, defaults to `standard`.',
      }),
    amount: z
      .string()
      .openapi({
        description:
          'Amount to discount by. For `percentage` discounts, must be an amount between `0.01` and `100`. For `flat` and `flat_per_seat` discounts, amount in the lowest denomination for a currency.',
      }),
    currency_code: z
      .union([CurrencyCodeSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Supported three-letter ISO 4217 currency code. Required where discount type is `flat` or `flat_per_seat`.',
      }),
    recur: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          'Whether this discount applies for multiple subscription billing periods (`true`) or not (`false`). If omitted, defaults to `false`.',
      }),
    maximum_recurring_intervals: z
      .union([z.int(), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "Number of subscription billing periods that this discount recurs for. Requires `recur`. `null` if this discount recurs forever.\n\nSubscription renewals, midcycle changes, and one-time charges billed to a subscription aren't considered a redemption. `times_used` is not incremented in these cases.",
      }),
    usage_limit: z
      .union([z.int(), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "Maximum number of times this discount can be redeemed. This is an overall limit for this discount, rather than a per-customer limit. `null` if this discount can be redeemed an unlimited amount of times.\n\nPaddle counts a usage as a redemption on a checkout, transaction, or the initial application against a subscription. Transactions created for subscription renewals, midcycle changes, and one-time charges aren't considered a redemption.\n\nPaddle checks this limit when a discount is applied to a checkout or transaction, comparing it against `times_used` at that moment. As `times_used` only increments when a transaction completes, checkouts that are open at the same time can each pass this check, so in some cases a discount may be redeemed more times than this limit allows.",
      }),
    restrict_to: z
      .union([z.array(DiscountRestrictToSchema), z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Product or price IDs that this discount is for. When including a product ID, all prices for that product can be discounted. `null` if this discount applies to all products and prices.',
      }),
    expires_at: z
      .union([TimestampSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          "RFC 3339 datetime string of when this discount expires. Discount can no longer be redeemed after this date has elapsed. `null` if this discount can be redeemed forever.\n\nExpired discounts can't be redeemed against transactions or checkouts, but can be applied when updating subscriptions.",
      }),
    custom_data: z
      .union([CustomDataSchema, z.null().nullable()])
      .exactOptional()
      .openapi({ description: 'Your own structured key-value data.' }),
    times_used: z
      .int()
      .exactOptional()
      .openapi({
        description:
          "How many times this discount has been redeemed. Automatically incremented by Paddle.\n\nPaddle counts a usage as a redemption on a checkout, transaction, or subscription. Transactions created for subscription renewals, midcycle changes, and one-time charges aren't considered a redemption.\n\nIncremented when a transaction completes, rather than when a discount is applied to a checkout. See `usage_limit` for how this affects enforcement of the limit.",
        readOnly: true,
      }),
    created_at: CreatedAtSchema.exactOptional().openapi({ readOnly: true }),
    updated_at: UpdatedAtSchema.exactOptional().openapi({ readOnly: true }),
    discount_group_id: z
      .union([DiscountGroupIdSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Paddle ID for the discount group related to this discount, prefixed with `dsg_`. `null` if not in a discount group.',
      }),
    import_meta: z
      .union([ImportMetaSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description: 'Import information for this entity. `null` if this entity is not imported.',
        'x-external-readOnly': true,
      }),
  })
  .openapi({
    required: ['description', 'type', 'amount'],
    description: 'Represents a discount entity when creating discounts.',
    title: 'DiscountCreate',
  })
  .openapi('DiscountCreate')

