const EventDataSchema = z
  .looseObject({})
  .superRefine((o, ctx) => {
    const e = new Set()
    const Schema = z.any()
    for (const [k, val] of Object.entries(o)) {
      if (e.has(k)) {
        continue
      }
      const result = Schema.safeParse(val)
      if (!result.success) {
        for (const issue of result.error.issues) {
          ctx.addIssue({ ...issue, path: [k, ...issue.path] })
        }
      }
    }
  })
  .openapi({ description: 'New or changed entity.', readOnly: true })
  .openapi('EventData')

