const MetricsExploreRequestSchema = z
  .object({
    entity: MetricEntitySchema.openapi({
      description:
        'Entity name for the metric to query. One metric per request. An unknown value, including `subscriptions` in sandbox, returns `unknown_entity`.',
    }),
    from: z
      .string()
      .openapi({
        description:
          "RFC 3339 datetime string or `YYYY-MM-DD` date for the start of the range, interpreted at 00:00 UTC. Inclusive. Must be within the metric's `max_lookback_days`, otherwise Paddle returns `max_lookback_exceeded`.",
        examples: ['2026-01-01'],
      }),
    to: z
      .string()
      .openapi({
        description:
          'RFC 3339 datetime string or `YYYY-MM-DD` date for the end of the range, interpreted at 00:00 UTC. Exclusive. Clamped to the current time if in the future.',
        examples: ['2026-04-01'],
      }),
    measures: z
      .array(MetricsExploreMeasureSchema)
      .min(1)
      .openapi({ description: 'One or more measures to compute.' }),
    interval: MetricsBucketIntervalSchema.default('month')
      .exactOptional()
      .openapi({
        description:
          'Interval that results are bucketed by. Every query is bucketed, so each entry in `timeseries` carries a `timestamp`.',
      }),
    dimensions: z
      .array(z.string())
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .default([])
      .exactOptional()
      .openapi({
        description:
          "Dimensions to group results by. Each combination of values returns as a segment. `timestamp` is implied by `interval`, so don't include it here.",
      }),
    filters: z
      .array(MetricsExploreFilterSchema)
      .default([])
      .exactOptional()
      .openapi({
        description:
          'Filters to narrow results by dimension. Multiple filters are combined, so results must match all of them.',
      }),
    order_by: z
      .array(MetricsExploreOrderBySchema)
      .exactOptional()
      .openapi({
        description:
          'Ordering. Required when you pass `dimensions`, because it decides which segments land on the page. Omitting it on a query with dimensions returns `invalid_field`.',
      }),
    per_page: z
      .int()
      .min(1)
      .max(50)
      .default(5)
      .exactOptional()
      .openapi({
        description:
          'Number of segments returned per page, not datapoints. Each segment carries its complete timeseries. Paddle returns the maximum if you request more, so check `meta.pagination.per_page` to see how many came back. A page can hold at most 10,000 datapoints (`per_page` multiplied by the time buckets in your range), otherwise Paddle returns `too_many_datapoints`.\n\nDefault: `5`; Maximum: `50`.',
      }),
  })
  .openapi({
    required: ['entity', 'from', 'to', 'measures'],
    description:
      'A JSON query against a single metric entity. Results are automatically scoped to your account.',
    title: 'Explore query request',
  })
  .openapi('MetricsExploreRequest')

