const SimulationIdSchema = z
  .string()
  .regex(/^ntfsim_[a-z\d]{26}$/)
  .openapi({
    description: 'Unique Paddle ID for this simulation, prefixed with `ntfsim_`.',
    title: 'Simulation ID',
    examples: ['ntfsim_01ghbkd0frb9k95cnhwd1bxpvk'],
    readOnly: true,
  })
  .openapi('SimulationId')

const SimulationPayloadSchema = z
  .looseObject({})
  .superRefine((o, ctx) => {
    const e = new Set()
    const Schema = z.any()
    for (const [k, val] of Object.entries(o)) {
      if (e.has(k)) {
        continue
      }
      const result = Schema.safeParse(val)
      if (!result.success) {
        for (const issue of result.error.issues) {
          ctx.addIssue({ ...issue, path: [k, ...issue.path] })
        }
      }
    }
  })
  .openapi({
    description: 'Simulation payload. A JSON object that matches the schema for an event type.',
    title: 'Simulation payload',
  })
  .openapi('SimulationPayload')

