const TransactionStatusQuerySchema = z
  .enum(['draft', 'ready', 'billed', 'paid', 'completed', 'canceled', 'past_due'])
  .openapi({
    'x-enum-descriptions': {
      draft: {
        description:
          'Return transactions where the status is `draft`. Returned transactions are missing required fields.',
      },
      ready: {
        description:
          'Return transactions where the status is `ready`. Returned transactions have all of the required fields to be marked as `billed` or `completed`.',
      },
      billed: {
        description:
          'Return transactions where the status is `billed`. Returned transactions are considered legal records and cannot be updated, only canceled.',
      },
      paid: {
        description:
          'Return transactions where the status is `paid`. Returned transactions are fully paid, but have not yet been fully processed internally.',
      },
      completed: {
        description:
          'Return transactions where the status is `completed`. Returned transactions are fully paid and processed.',
      },
      canceled: {
        description:
          'Return transactions where the status is `canceled`. Returned transactions have been canceled and are no longer due.',
      },
      past_due: {
        description:
          'Return transactions where the status is `past_due`. Returned transactions are past due, meaning payment failed for automatically-collected transactions or no payment was received 24 hours after the due date for manually-collected transactions.',
      },
    },
  })
  .openapi('TransactionStatusQuery')

