const VerificationStatusSchema = z
  .enum([
    'pending',
    'in_progress',
    'in_review',
    'action_required',
    'completed',
    'failed',
    'canceled',
  ])
  .openapi({
    description: 'Overall status of the verification, derived from the status of its steps.',
    title: 'Verification status',
    'x-enum-descriptions': {
      pending: {
        description: "Verification hasn't started, or is waiting for its next step to start.",
      },
      in_progress: { description: 'Paddle is running automated checks. No input is required.' },
      in_review: {
        description: 'Paddle is reviewing the information provided by the account holder.',
      },
      action_required: { description: 'Action is required before the verification can continue.' },
      completed: {
        description:
          'Verification is complete. For an `onboarding` verification, the account is ready for live payments.',
      },
      failed: { description: "Verification didn't complete." },
      canceled: {
        description:
          'Verification was canceled and will not continue. No further action is required.',
      },
    },
  })
  .openapi('VerificationStatus')

