const FilterIdParamParamsSchema = z
  .preprocess(
    (val) =>
      val === undefined
        ? val
        : (Array.isArray(val) ? val : [val]).flatMap((item) =>
            typeof item === 'string' ? item.split(',') : [item],
          ),
    z.array(z.string()),
  )
  .exactOptional()
  .openapi({
    param: {
      name: 'id',
      in: 'query',
      required: false,
      description:
        'Return only the IDs specified. Use a comma-separated list to get multiple entities.',
      schema: { type: 'array', items: { type: 'string' } },
      explode: false,
    },
  })

const PaginationParamsAfterParamsSchema = z
  .string()
  .exactOptional()
  .openapi({
    param: {
      name: 'after',
      in: 'query',
      required: false,
      description:
        'Return entities after the specified Paddle ID when working with paginated endpoints. Used in the `meta.pagination.next` URL in responses for list operations.',
      schema: { type: 'string' },
      explode: false,
    },
  })

const PaginationParamsPerPageParamsSchema = z
  .preprocess(
    (val) =>
      typeof val === 'string' &&
      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
        ? Number(val)
        : val,
    z.int().max(200),
  )
  .default(50)
  .exactOptional()
  .openapi({
    param: {
      name: 'per_page',
      in: 'query',
      required: false,
      description:
        'Set how many entities are returned per page. Paddle returns the maximum number of results if a number greater than the maximum is requested. Check `meta.pagination.per_page` in the response to see how many were returned.\n\nDefault: `50`; Maximum: `200`.',
      schema: { type: 'integer', maximum: 200, default: 50 },
      explode: false,
    },
  })

