export const getCustomersCustomerIdCreditBalancesRoute = createRoute({
  method: 'get',
  path: '/customers/{customer_id}/credit-balances',
  tags: ['Customers'],
  summary: 'List credit balances for a customer',
  description:
    "Returns a list of credit balances for each currency for a customer. Each balance has three totals:\n\n* `available`: total available to use.\n* `reserved`: total temporarily reserved for billed transactions.\n* `used`: total amount of credit used.\n\nCredit is added to the `available` total initially. When used, it moves to the `used` total.\n\nThe `reserved` total is used when a credit balance is applied to a transaction that's marked as `billed`, like when working with an issued invoice. It's not available for other transactions at this point, but isn't considered `used` until the transaction is completed. If a `billed` transaction is `canceled`, any reserved credit moves back to `available`.\n\nCredit balances are created automatically by Paddle when you take an action that results in Paddle creating a credit for a customer, like making prorated changes to a subscription. An empty `data` array is returned where a customer has no credit balances.\n\nThe response is not paginated.",
  externalDocs: {
    url: 'https://developer.paddle.com/api-reference/customers/list-credit-balances',
    description: 'List credit balances for a customer',
  },
  operationId: 'list-credit-balances',
  request: {
    params: z.object({ customer_id: CustomerIdPathParamParamsSchema }),
    query: z.object({ currency_code: ListCreditBalancesQueryParamsParamsSchema }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: {
        'application/json': {
          schema: z
            .object({ data: z.array(CreditBalanceSchema), meta: MetaSchema })
            .openapi({ required: ['data', 'meta'] }),
          examples: {
            'List credit balances for a customer (200)': {
              summary: 'List credit balances for a customer (200)',
              value: {
                data: [
                  {
                    customer_id: 'ctm_01gw9m680k848184fpttwr0b7z',
                    currency_code: 'USD',
                    balance: { available: '550', reserved: '900', used: '1300' },
                  },
                ],
                meta: { request_id: '32cf1966-ed49-47d6-a76a-a9b8f7843245' },
              },
            },
          },
        },
      },
      headers: z.object({ 'Request-Id': RequestIdSchema }),
    },
    default: {
      description: 'An unexpected error response.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
})

