export const getSettingsTaxRoute = createRoute({
  method: 'get',
  path: '/settings/tax',
  tags: ['Settings'],
  summary: 'Get tax settings',
  description:
    'Returns the tax settings for your account.\n\nIncludes the default tax mode (`default_tax_mode`) that Paddle uses for prices with a `tax_mode` of `account_setting`.',
  externalDocs: {
    url: 'https://developer.paddle.com/api-reference/settings/get-tax-settings',
    description: 'Get tax settings',
  },
  operationId: 'get-tax-settings',
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: {
        'application/json': {
          schema: z
            .object({ data: TaxSettingsSchema, meta: MetaSchema })
            .openapi({ required: ['data', 'meta'] }),
          examples: {
            'Get tax settings (200)': {
              summary: 'Get tax settings (200)',
              value: {
                data: { default_tax_mode: 'exclusive' },
                meta: { request_id: '9bcdcc29-e180-4055-ad3d-d37e5dc5e56d' },
              },
            },
          },
        },
      },
      headers: z.object({ 'Request-Id': RequestIdSchema }),
    },
    default: {
      description: 'An unexpected error response.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
})

