export const getTransactionsTransactionIdInvoiceRoute = createRoute({
  method: 'get',
  path: '/transactions/{transaction_id}/invoice',
  tags: ['Transactions'],
  summary: 'Get a PDF invoice for a transaction',
  description:
    "Returns a link to an invoice PDF for a transaction.\n\nInvoice PDFs are available for both automatically and manually-collected transactions:\n\n* The PDF for manually-collected transactions includes payment terms, purchase order number, and notes for your customer. It's a demand for payment from your customer. It's available for transactions that are `billed` or `completed`.\n* The PDF for automatically-collected transactions lets your customer know that payment was taken successfully. Customers may require this for for tax-reporting purposes. It's available for transactions that are `completed`.\n\nInvoice PDFs aren't available for zero-value transactions.\n\nThe link returned is not a permanent link. It expires after an hour.",
  externalDocs: {
    url: 'https://developer.paddle.com/api-reference/transactions/get-invoice-pdf',
    description: 'Get a PDF invoice for a transaction',
  },
  operationId: 'get-transaction-invoice',
  request: {
    params: z.object({ transaction_id: TransactionIdPathParamParamsSchema }),
    query: z.object({ disposition: GetInvoicePdfParamsParamsSchema }),
  },
  responses: {
    200: {
      description: 'The request has succeeded.',
      content: {
        'application/json': {
          schema: GetInvoicePdfResponseSchema,
          examples: {
            'Get a PDF invoice for a transaction (200)': {
              summary: 'Get a PDF invoice for a transaction (200)',
              value: {
                data: {
                  url: 'https://paddle-production-invoice-service-pdfs.s3.amazonaws.com/invoices/10889/e01ae945-9e6d-4208-a0ba-83b107e06657/invoice_325-10650_DX-ChatApp.pdf',
                },
                meta: { request_id: '126c131a-258a-482b-b4a9-9ffca5126539' },
              },
            },
          },
        },
      },
      headers: z.object({
        Expires: z.string().openapi({ description: 'Date and time when this resource expires.' }),
        'Request-Id': RequestIdSchema,
      }),
    },
    default: {
      description: 'An unexpected error response.',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
})

